17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	import java.util.UUID;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!normalizeNewOwner(owner)) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (dailyLimitReached(owner.getRegistrationDate())) {
116	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
117	        }
118	        if (cityIsAtCapacity(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        Optional<Owner> householdMember = findHouseholdMember(owner);
125	        if (householdMember.isPresent()) {
126	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
127	                return new ResponseEntity<>(HttpStatus.CONFLICT);
128	            }
129	            joinHousehold(owner, householdMember.get());
130	        }
131	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
132	        owner.setNamesakeCount(countNamesakes(owner));
133	        owner.setMembershipNumber(membershipNumber(owner));
134	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
135	        owner.setHouseholdSize(householdSize(owner));
136	        this.clinicService.saveOwner(owner);
137	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
138	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        headers.setLocation(UriComponentsBuilder.newInstance()
141	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
142	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
157	        String email = ownerFieldsDto.getEmail();
158	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
159	        this.clinicService.saveOwner(currentOwner);
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Transactional
165	    @Override
166	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        this.clinicService.deleteOwner(owner);
172	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        HttpHeaders headers = new HttpHeaders();
183	        Pet pet = petMapper.toPet(petFieldsDto);
184	        owner.setId(ownerId);
185	        pet.setOwner(owner);
186	        pet.getType().setName(null);
187	        this.clinicService.savePet(pet);
188	        PetDto petDto = petMapper.toPetDto(pet);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
190	            .buildAndExpand(pet.getId()).toUri());
191	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner != null) {
199	            Pet currentPet = this.clinicService.findPetById(petId);
200	            if (currentPet != null) {
201	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
202	                currentPet.setName(petFieldsDto.getName());
203	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
204	                this.clinicService.savePet(currentPet);
205	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
214	        HttpHeaders headers = new HttpHeaders();
215	        Visit visit = visitMapper.toVisit(visitFieldsDto);
216	        Pet pet = new Pet();
217	        pet.setId(petId);
218	        visit.setPet(pet);
219	        this.clinicService.saveVisit(visit);
220	        VisitDto visitDto = visitMapper.toVisitDto(visit);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
222	            .buildAndExpand(visit.getId()).toUri());
223	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
224	    }
225	
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner != null) {
232	            Pet pet = owner.getPet(petId);
233	            if (pet != null) {
234	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    /**
241	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
242	     * the canonical form each stored value must take: the address is trimmed,
243	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
244	     * telephone is converted to E.164, any email is lower-cased and a missing
245	     * registration date defaults to today. Field-level rejections are reported here
246	     * rather than inline in {@link #addOwner}, and normalisation runs before any
247	     * household comparison so those comparisons see the canonical values.
248	     *
249	     * @param owner the freshly-mapped owner to normalise
250	     * @return {@code true} if the fields are valid, or {@code false} if the address
251	     *         is blank after normalisation or the telephone cannot form a valid
252	     *         E.164 number, in which case the request must be rejected with
253	     *         {@code 400 Bad Request}
254	     */
255	    private boolean normalizeNewOwner(Owner owner) {
256	        String address = Owner.normalizeAddress(owner.getAddress());
257	        if (address.isEmpty()) {
258	            return false;
259	        }
260	        owner.setAddress(address);
261	        String telephone = toE164(owner.getTelephone());
262	        if (telephone == null) {
263	            return false;
264	        }
265	        owner.setTelephone(telephone);
266	        if (owner.getEmail() != null) {
267	            owner.setEmail(owner.getEmail().toLowerCase());
268	        }
269	        if (owner.getRegistrationDate() == null) {
270	            owner.setRegistrationDate(LocalDate.now());
271	        }
272	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
273	        return true;
274	    }
275	
276	    /**
277	     * Roll the given date forward to the next business day when it falls on a
278	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
279	     * weekday is returned unchanged. Applied to the effective registration date
280	     * (whether supplied in the request or defaulted to the server date) so that
281	     * every value derived from it uses the adjusted business day.
282	     *
283	     * @param date the effective registration date
284	     * @return the same date if it is a weekday, otherwise the next Monday
285	     */
286	    private static LocalDate rollToBusinessDay(LocalDate date) {
287	        switch (date.getDayOfWeek()) {
288	            case SATURDAY:
289	                return date.plusDays(2);
290	            case SUNDAY:
291	                return date.plusDays(1);
292	            default:
293	                return date;
294	        }
295	    }
296	
297	    /**
298	     * Find an existing owner that belongs to the same household as the given owner,
299	     * i.e. shares the same last name and address (compared case-insensitively with
300	     * runs of whitespace collapsed to a single space).
301	     *
302	     * @param owner the candidate owner being created
303	     * @return the matching existing owner, or empty if none exists
304	     */
305	    private Optional<Owner> findHouseholdMember(Owner owner) {
306	        return this.clinicService.findAllOwners().stream()
307	            .filter(existing -> existing.sameHouseholdAs(owner))
308	            .findFirst();
309	    }
310	
311	    /**
312	     * Assign the joining owner and an existing household member the same stable
313	     * household identifier. The identifier is derived deterministically from the
314	     * shared household key (last name + address, normalised), so every owner in a
315	     * household resolves to the same value; the existing member is updated when it
316	     * does not already carry it.
317	     *
318	     * @param owner    the owner being created
319	     * @param existing an existing owner in the same household
320	     */
321	    private void joinHousehold(Owner owner, Owner existing) {
322	        String householdId = UUID
323	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
324	        owner.setHouseholdId(householdId);
325	        if (!householdId.equals(existing.getHouseholdId())) {
326	            existing.setHouseholdId(householdId);
327	            this.clinicService.saveOwner(existing);
328	        }
329	    }
330	
331	    /**
332	     * Count how many owners belong to the given owner's household once this create
333	     * completes: the owners that already share its {@code householdId} plus the owner
334	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
335	     * so the household identifier (and any existing member updated to it) is already in
336	     * place. An owner that has not joined a household (no {@code householdId}) is a
337	     * household of one.
338	     *
339	     * @param owner the candidate owner being created, after household resolution
340	     * @return the household member count after this create (at least {@code 1})
341	     */
342	    private int householdSize(Owner owner) {
343	        String householdId = owner.getHouseholdId();
344	        if (householdId == null) {
345	            return 1;
346	        }
347	        long existing = this.clinicService.findAllOwners().stream()
348	            .filter(other -> householdId.equals(other.getHouseholdId()))
349	            .count();
350	        return (int) existing + 1;
351	    }
352	
353	    /**
354	     * Count the existing owners that share the given owner's first and last name,
355	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
356	     * before the new owner is saved, so the result reflects only owners that
357	     * already existed at creation time.
358	     *
359	     * @param owner the candidate owner being created
360	     * @return the number of existing namesakes
361	     */
362	    private int countNamesakes(Owner owner) {
363	        String firstName = normalizeName(owner.getFirstName());
364	        String lastName = normalizeName(owner.getLastName());
365	        return (int) this.clinicService.findAllOwners().stream()
366	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
367	                && normalizeName(existing.getLastName()).equals(lastName))
368	            .count();
369	    }
370	
371	    private static String normalizeName(String value) {
372	        return value == null ? "" : value.trim().toLowerCase();
373	    }
374	
375	    /**
376	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
377	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
378	     * first three letters of the given last name and NNNN a per-city 4-digit
379	     * zero-padded sequence equal to one more than the number of owners already in
380	     * that city (e.g. {@code SYD-SMI-0007}).
381	     *
382	     * @param city     the owner's city
383	     * @param lastName the owner's last name
384	     * @return the assigned customer code
385	     */
386	    /**
387	     * Determine whether the given city has already reached its owner capacity, i.e.
388	     * it already contains 50 or more existing owners (compared case-insensitively
389	     * with surrounding whitespace trimmed). A new owner may not be created in a city
390	     * that is at capacity.
391	     *
392	     * @param city the candidate owner's city
393	     * @return {@code true} if the city already holds 50 or more owners
394	     */
395	    private boolean cityIsAtCapacity(String city) {
396	        String normalizedCity = normalizeName(city);
397	        long count = this.clinicService.findAllOwners().stream()
398	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
399	            .count();
400	        return count >= 50;
401	    }
402	
403	    /**
404	     * Determine whether the daily owner-creation limit has already been reached, i.e.
405	     * 100 or more owners already carry the given registration date. A new owner may
406	     * not be created once that day's cap is reached.
407	     *
408	     * @param registrationDate the registration date the new owner would be created with
409	     * @return {@code true} if 100 or more existing owners share that registration date
410	     */
411	    private boolean dailyLimitReached(LocalDate registrationDate) {
412	        long count = this.clinicService.findAllOwners().stream()
413	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
414	            .count();
415	        return count >= 100;
416	    }
417	
418	    /**
419	     * Determine whether more than 80 owners have already been created for the given
420	     * registration date, i.e. strictly more than 80 existing owners carry that date.
421	     * Evaluated before the new owner is saved, so it reflects only owners that
422	     * already existed at creation time.
423	     *
424	     * @param registrationDate the registration date the new owner would be created with
425	     * @return {@code true} if more than 80 existing owners share that registration date
426	     */
427	    private boolean bulkSignupWarning(LocalDate registrationDate) {
428	        long count = this.clinicService.findAllOwners().stream()
429	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
430	            .count();
431	        return count > 80;
432	    }
433	
434	    private String nextCustomerCode(String city, String lastName) {
435	        String city3 = prefix3(city);
436	        String last3 = prefix3(lastName);
437	        long sequence = this.clinicService.findAllOwners().stream()
438	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
439	            .count() + 1L;
440	        return String.format("%s-%s-%04d", city3, last3, sequence);
441	    }
442	
443	    private static String prefix3(String value) {
444	        String v = value == null ? "" : value;
445	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
446	    }
447	
448	    /**
449	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
450	     * where {@code <customerCode>} is the owner's already-assigned customer code and
451	     * YY is the last two digits of the registration date's year (e.g.
452	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
453	     * have been set.
454	     *
455	     * @param owner the owner being created, with customer code and registration date
456	     *              already assigned
457	     * @return the assigned membership number
458	     */
459	    private String membershipNumber(Owner owner) {
460	        int yy = owner.getRegistrationDate().getYear() % 100;
461	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
462	    }
463	
464	    /**
465	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
466	     * code when present, otherwise assume country code '+61' and drop a single
467	     * leading '0' from the national digits. Spaces, dashes and brackets are
468	     * stripped. The result must contain 8 to 15 digits after the '+'.
469	     *
470	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
471	     *         input cannot form a valid E.164 number.
472	     */
473	    private static String toE164(String raw) {
474	        if (raw == null) {
475	            return null;
476	        }
477	        String cleaned = raw.replaceAll("[\\s()-]", "");
478	        String digits;
479	        if (cleaned.startsWith("+")) {
480	            digits = cleaned.substring(1);
481	        } else {
482	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
483	            digits = "61" + national;
484	        }
485	        if (!digits.matches("\\d{8,15}")) {
486	            return null;
487	        }
488	        return "+" + digits;
489	    }
490	}
