28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
41	    private static final Map<String, String> CITY_REGION = Map.of(
42	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    @Email
59	    private String email;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "membership_number")
74	    private String membershipNumber;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    public String getAddress() {
86	        return this.address;
87	    }
88	
89	    public void setAddress(String address) {
90	        this.address = address;
91	    }
92	
93	    public String getCity() {
94	        return this.city;
95	    }
96	
97	    public void setCity(String city) {
98	        this.city = city;
99	    }
100	
101	    /**
102	     * The canonical region derived from this owner's {@link #city} using the fixed
